import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { redirect } from "next/navigation";
import Link from "next/link";
import { db } from "@/lib/db";
import BalanceChart from "@/components/BalanceChart";

export default async function DashboardPage() {
  const session = await getServerSession(authOptions);

  if (!session) {
    redirect("/login");
  }

  const user = session.user as any;

  // Fetch real account balance and recent transactions from the database
  const dbUser = await db.user.findUnique({
    where: { email: user.email },
    include: {
      account: true,
      transactions: {
        orderBy: { createdAt: "desc" },
        take: 5,
      },
    },
  });

  const account = dbUser?.account;
  const transactions = dbUser?.transactions || [];
  const balance = account ? Number(account.balance) : 0.00;
  const savingsBalance = account ? Number(account.savingsBalance || 0) : 0.00;
  const investmentBalance = account ? Number(account.investmentBalance || 0) : 0.00;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex">
      {/* Sidebar Navigation */}
      <aside className="w-64 bg-slate-900 border-r border-slate-800 flex flex-col hidden md:flex">
        <div className="p-6 border-b border-slate-800">
          <h1 className="text-xl font-bold tracking-wider text-indigo-400">CivicBank</h1>
          <p className="text-xs text-slate-400 mt-1">Customer portal</p>
        </div>

        <nav className="flex-1 p-4 space-y-1.5 overflow-y-auto">
          {[
            { name: "Overview", href: "/dashboard", active: true },
            { name: "Accounts", href: "/dashboard/accounts", active: false },
            { name: "Transfers", href: "/dashboard/transfers", active: false },
            { name: "Deposits", href: "/dashboard/deposits", active: false },
            { name: "Withdrawals", href: "/dashboard/withdrawals", active: false },
            { name: "Savings", href: "/dashboard/savings", active: false },
            { name: "Investments", href: "/dashboard/investments", active: false },
            { name: "Loans", href: "/dashboard/loans", active: false },
            { name: "Statements", href: "/dashboard/statements", active: false },
            { name: "Support", href: "/dashboard/support", active: false },
            { name: "Settings", href: "/dashboard/settings", active: false },
          ].map((item) => (
            <Link
              key={item.name}
              href={item.href}
              className={`flex items-center px-4 py-2.5 rounded-lg text-sm font-medium transition-colors ${
                item.active
                  ? "bg-indigo-600/10 text-indigo-400 border border-indigo-500/20"
                  : "text-slate-400 hover:bg-slate-800 hover:text-slate-200"
              }`}
            >
              <span>{item.name}</span>
            </Link>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-800">
          <div className="px-3 py-2 mb-2">
            <p className="text-sm font-medium text-slate-200 truncate">{user?.name || "Customer"}</p>
            <p className="text-xs text-slate-400 truncate">{user?.email}</p>
          </div>
          <Link
            href="/api/auth/signout"
            className="w-full flex items-center justify-center space-x-2 bg-red-500/10 hover:bg-red-500/20 text-red-400 py-2 rounded-lg text-sm font-medium transition-colors border border-red-500/20"
          >
            <span>Sign Out</span>
          </Link>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 overflow-y-auto">
        <header className="bg-slate-900 border-b border-slate-800 h-16 flex items-center justify-between px-6 sticky top-0 z-10">
          <div>
            <h2 className="text-lg font-semibold text-slate-200">Good morning, {user?.name || "Customer"}</h2>
            <p className="text-xs text-slate-400">Personal banking overview · September 15, 2026</p>
          </div>
          <div className="flex items-center space-x-3">
            <span className="text-xs bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-3 py-1 rounded-full font-medium">
              Live Secure Session (USD)
            </span>
          </div>
        </header>

        <div className="p-6 space-y-6 max-w-7xl w-full mx-auto">
          {/* Quick Action Navigation Toolbar */}
          <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3">
            <Link href="/dashboard/transfers" className="bg-slate-900 hover:bg-slate-800/80 border border-slate-800 p-3 rounded-xl text-center transition-colors">
              <span className="text-lg">💸</span>
              <p className="text-xs font-medium text-slate-200 mt-1">Transfer</p>
            </Link>
            <Link href="/dashboard/deposits" className="bg-slate-900 hover:bg-slate-800/80 border border-slate-800 p-3 rounded-xl text-center transition-colors">
              <span className="text-lg">📥</span>
              <p className="text-xs font-medium text-slate-200 mt-1">Deposit</p>
            </Link>
            <Link href="/dashboard/withdrawals" className="bg-slate-900 hover:bg-slate-800/80 border border-slate-800 p-3 rounded-xl text-center transition-colors">
              <span className="text-lg">📤</span>
              <p className="text-xs font-medium text-slate-200 mt-1">Withdraw</p>
            </Link>
            <Link href="/dashboard/savings" className="bg-slate-900 hover:bg-slate-800/80 border border-slate-800 p-3 rounded-xl text-center transition-colors">
              <span className="text-lg">🏦</span>
              <p className="text-xs font-medium text-slate-200 mt-1">Savings</p>
            </Link>
            <Link href="/dashboard/investments" className="bg-slate-900 hover:bg-slate-800/80 border border-slate-800 p-3 rounded-xl text-center transition-colors">
              <span className="text-lg">📈</span>
              <p className="text-xs font-medium text-slate-200 mt-1">Invest</p>
            </Link>
            <Link href="/dashboard/loans" className="bg-slate-900 hover:bg-slate-800/80 border border-slate-800 p-3 rounded-xl text-center transition-colors">
              <span className="text-lg">💳</span>
              <p className="text-xs font-medium text-slate-200 mt-1">Loans</p>
            </Link>
          </div>

          {/* KPI Summary Cards */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
            <div className="bg-slate-900 border border-slate-800 p-5 rounded-xl shadow-lg">
              <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Available balance</span>
              <div className="text-2xl font-bold text-white mt-2">
                ${balance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
              </div>
            </div>

            <div className="bg-slate-900 border border-slate-800 p-5 rounded-xl shadow-lg">
              <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Savings</span>
              <div className="text-2xl font-bold text-emerald-400 mt-2">
                ${savingsBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
              </div>
            </div>

            <div className="bg-slate-900 border border-slate-800 p-5 rounded-xl shadow-lg">
              <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Investments</span>
              <div className="text-2xl font-bold text-indigo-400 mt-2">
                ${investmentBalance.toLocaleString(undefined, { minimumFractionDigits: 2 })}
              </div>
            </div>

            <div className="bg-slate-900 border border-slate-800 p-5 rounded-xl shadow-lg">
              <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Loan outstanding</span>
              <div className="text-2xl font-bold text-amber-400 mt-2">$0.00</div>
            </div>
          </div>

          {/* Analytics & Account Details Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 bg-slate-900 border border-slate-800 p-6 rounded-xl shadow-lg flex flex-col">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-base font-semibold text-slate-200">Balance trend</h3>
                <span className="text-xs text-slate-400 bg-slate-800 px-2.5 py-1 rounded">2026 Performance</span>
              </div>
              <div className="h-64 w-full">
                <BalanceChart />
              </div>
            </div>

            <div className="bg-slate-900 border border-slate-800 p-6 rounded-xl shadow-lg flex flex-col justify-between">
              <div>
                <h3 className="text-base font-semibold text-slate-200 mb-4">Account details</h3>
                <div className="space-y-4 text-sm">
                  <div>
                    <p className="text-xs text-slate-400">Account number</p>
                    <p className="font-mono font-bold text-white text-base tracking-wide mt-0.5">
                      {account?.accountNumber || "CB-1029384756"}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs text-slate-400">Type</p>
                    <p className="font-semibold text-slate-200 mt-0.5">USD Checking / Savings Tier 1</p>
                  </div>
                  <div>
                    <p className="text-xs text-slate-400">Status</p>
                    <span className="inline-block mt-1 px-2.5 py-0.5 text-xs rounded-full font-medium bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                      Active
                    </span>
                  </div>
                </div>
              </div>
              <div className="mt-6 pt-4 border-t border-slate-800 flex gap-2">
                <Link
                  href="/dashboard/transfers"
                  className="flex-1 flex items-center justify-center py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-xs font-medium transition-colors"
                >
                  Transfer
                </Link>
                <Link
                  href="/dashboard/deposits"
                  className="flex-1 flex items-center justify-center py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 rounded-lg text-xs font-medium transition-colors"
                >
                  Deposit
                </Link>
              </div>
            </div>
          </div>

          {/* Recent Transactions Table */}
          <div className="bg-slate-900 border border-slate-800 rounded-xl shadow-lg overflow-hidden">
            <div className="p-6 border-b border-slate-800 flex justify-between items-center">
              <h3 className="text-base font-semibold text-slate-200">Recent transactions</h3>
              <Link href="/dashboard/transfers" className="text-xs text-indigo-400 hover:underline">
                View All
              </Link>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-950/50 text-slate-400 text-xs uppercase tracking-wider border-b border-slate-800">
                    <th className="py-3 px-6">Transaction Type</th>
                    <th className="py-3 px-6">Amount</th>
                    <th className="py-3 px-6">Direction</th>
                    <th className="py-3 px-6">Status</th>
                    <th className="py-3 px-6">Date</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800 text-sm text-slate-300">
                  {transactions.length > 0 ? (
                    transactions.map((tx: any) => (
                      <tr key={tx.id} className="hover:bg-slate-800/50 transition-colors">
                        <td className="py-4 px-6 font-medium text-white">{tx.type}</td>
                        <td className="py-4 px-6 font-semibold">${Number(tx.amount).toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
                        <td className="py-4 px-6">
                          <span className={`font-bold ${tx.type === 'DEPOSIT' ? 'text-emerald-400' : 'text-slate-300'}`}>
                            {tx.type === 'DEPOSIT' ? '+' : '-'}
                          </span>
                        </td>
                        <td className="py-4 px-6">
                          <span className={`px-2.5 py-1 text-xs rounded-full font-medium ${
                            tx.status === 'COMPLETED' ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' :
                            tx.status === 'PENDING' ? 'bg-amber-500/10 text-amber-400 border border-amber-500/20' :
                            'bg-red-500/10 text-red-400 border border-red-500/20'
                          }`}>
                            {tx.status}
                          </span>
                        </td>
                        <td className="py-4 px-6 text-slate-400 text-xs">
                          {new Date(tx.createdAt).toLocaleDateString()}
                        </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan={5} className="py-8 text-center text-slate-500 text-sm">
                        No transactions found.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}